	/**
	 * @param string $field year|mileage|power|engine|fuel|transmission|condition|mot
	 * @param string $code  Selected value, when the symbol depends on it.
	 * @return string
	 */
	public static function raw( $field, $code = '' ) {
		$field = (string) $field;
		$code  = (string) $code;
		if ( 'year' === $field ) {
			return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M8 2v4"/><path d="M16 2v4"/><rect width="18" height="18" x="3" y="4" rx="2"/><path d="M3 10h18"/></svg>';
		}
		if ( 'mileage' === $field ) {
			return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg>';
		}
		if ( 'power' === $field || 'power_kw' === $field ) {
			return self::units()['power'];
		}
		if ( 'engine' === $field || 'engine_cc' === $field ) {
			return self::units()['engineCc'];
		}
		if ( 'fuel' === $field ) {
			$map = self::fuels();
			if ( '' === $code ) {
				return $map['benzin'] ?? '';
			}
			return $map[ $code ] ?? ( $map['other'] ?? '' );
		}
		if ( 'transmission' === $field ) {
			$map = self::transmissions();
			return $map[ $code ] ?? ( $map['manual'] ?? '' );
		}
		if ( 'condition' === $field ) {
			$map = self::conditions();
			return $map[ $code ] ?? ( $map['good'] ?? '' );
		}
		if ( 'mot' === $field ) {
			$map = self::mots();
			$key = ( 'no' === $code || '0' === $code ) ? 'no' : 'yes';
			return $map[ $key ] ?? '';
		}
		if ( 'body' === $field ) {
			return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M19 17h2c.6 0 1-.4 1-1v-3c0-.9-.7-1.7-1.5-1.9C18.7 10.6 16 10 16 10s-1.3-1.4-2.2-2.3c-.5-.4-1.1-.7-1.8-.7H5c-.6 0-1.1.4-1.4.9l-1.4 2.9A3.7 3.7 0 0 0 2 12v4c0 .6.4 1 1 1h2"/><circle cx="7" cy="17" r="2"/><path d="M9 17h6"/><circle cx="17" cy="17" r="2"/></svg>';
		}
		if ( 'owners' === $field ) {
			return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>';
		}
		return '';
	}

	/**
	 * @param string $field Field key.
	 * @param string $code  Selected value.
	 * @param int    $size  Pixel size.
	 * @return string
	 */
	public static function render( $field, $code = '', $size = 16 ) {
		$svg = self::raw( $field, $code );
		if ( '' === $svg ) {
			return '';
		}
		$size = max( 12, (int) $size );
		if ( false !== strpos( $svg, 'class="' ) ) {
			$svg = preg_replace( '/class="/', 'class="kmae-vehicle-icon ', $svg, 1 );
			$svg = preg_replace( '/<svg\b/', '<svg width="' . $size . '" height="' . $size . '"', $svg, 1 );
		} else {
			$svg = preg_replace( '/<svg\b/', '<svg width="' . $size . '" height="' . $size . '" class="kmae-vehicle-icon"', $svg, 1 );
		}
		return $svg;
	}

	/**
	 * Catalog passed to the listing wizard so the cards use these same drawings.
	 *
	 * @return array<string,mixed>
	 */
	public static function js_catalog() {
		return array(
			'fuel'         => self::fuels(),
			'unit'         => self::units(),
			'transmission' => self::transmissions(),
			'mot'          => self::mots(),
			'condition'    => self::conditions(),
		);
	}
}
